-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Vor- Nachteile von Unternehmensformen > Einfachheit bei Einzelunternehmen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Einzelunternehmen ohne notarielle Beurkundung gegründet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Einzelunternehmen erfordert keine notarielle Beurkundung"}, {"text": "Nein", "correct": false, "because": "Einfachheit ist ein Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Einfachheit der Gründung eines IT-Einzelunternehmens ein Vorteil gegenüber einer GmbH?', 2, '[{"text": "Ja", "correct": true, "because": "GmbH erfordert Notar und Mindestkapital"}, {"text": "Nein", "correct": false, "because": "Einfachheit ist ein klarer Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert die Einfachheit eines IT-Einzelunternehmens eine komplexe Buchführung?', 2, '[{"text": "Nein", "correct": true, "because": "EÜR ist bei geringem Umsatz ausreichend"}, {"text": "Ja", "correct": false, "because": "Einfachheit reduziert Buchführungsaufwand"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Einfachheit eines IT-Einzelunternehmens die Entscheidungsfindung beschleunigen?', 2, '[{"text": "Ja", "correct": true, "because": "Unternehmer entscheidet allein"}, {"text": "Nein", "correct": false, "because": "Keine Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Einfachheit eines IT-Einzelunternehmens ein Nachteil bei der Kapitalbeschaffung?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Kapitalstruktur für Investoren"}, {"text": "Nein", "correct": false, "because": "Einfachheit schränkt Kapitalzufluss ein"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bedeutet die Einfachheit bei einem IT-Einzelunternehmen?', 2, '[{"text": "Geringe Gründungsformalitäten", "correct": true, "because": "Keine Notar- oder Kapitalvorgaben"}, {"text": "Hoher Verwaltungsaufwand", "correct": false, "because": "Einfachheit reduziert Aufwand"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Das ist kein Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Einfachheit ist für ein IT-Einzelunternehmen am bedeutendsten?', 3, '[{"text": "Keine Mindestkapitalvorgabe", "correct": true, "because": "Reduziert Gründungsaufwand"}, {"text": "Komplexe Buchführung", "correct": false, "because": "EÜR ist einfach"}, {"text": "Mehrere Gesellschafter", "correct": false, "because": "Nur ein Unternehmer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus der Einfachheit eines IT-Einzelunternehmens?', 3, '[{"text": "Schnelle Gründung", "correct": true, "because": "Wenige Formalien beschleunigen Prozess"}, {"text": "Hohe Kapitalaufnahme", "correct": false, "because": "Kapitalbeschaffung eingeschränkt"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Haftung ist unbeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung entfällt durch die Einfachheit eines IT-Einzelunternehmens?', 2, '[{"text": "Notarielle Beurkundung", "correct": true, "because": "Keine notarielle Gründung nötig"}, {"text": "Gewerbeanmeldung", "correct": false, "because": "Gewerbeanmeldung bleibt Pflicht"}, {"text": "Steuerliche Registrierung", "correct": false, "because": "Steuerpflicht bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil der Einfachheit eines IT-Einzelunternehmens?', 3, '[{"text": "Eingeschränkte Kapitalmöglichkeiten", "correct": true, "because": "Keine Struktur für Investoren"}, {"text": "Hohe Verwaltungskosten", "correct": false, "because": "Verwaltung ist einfach"}, {"text": "Komplexe Entscheidungsfindung", "correct": false, "because": "Entscheidungen sind schnell"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einfachheit eines IT-Einzelunternehmens?', 4, '[{"text": "Geringe Gründungskosten", "correct": true, "because": "Keine Notar- oder Kapitalkosten"}, {"text": "Schnelle Entscheidungsfindung", "correct": true, "because": "Unternehmer entscheidet allein"}, {"text": "Hohe Kapitalaufnahme", "correct": false, "because": "Kapitalbeschaffung eingeschränkt"}, {"text": "Geringer Verwaltungsaufwand", "correct": true, "because": "Wenige Formalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile ergeben sich aus der Einfachheit eines IT-Einzelunternehmens?', 3, '[{"text": "Eingeschränkte Kapitalbeschaffung", "correct": true, "because": "Nur eigenes Kapital"}, {"text": "Keine Haftungsbeschränkung", "correct": true, "because": "Unbeschränkte Haftung bleibt"}, {"text": "Hoher Gründungsaufwand", "correct": false, "because": "Gründung ist einfach"}, {"text": "Wenig Entscheidungsfreiheit", "correct": false, "because": "Entscheidungen sind flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale der Einfachheit zeichnen ein IT-Einzelunternehmen aus?', 4, '[{"text": "Keine Mindestkapitalvorgabe", "correct": true, "because": "Kein Kapital erforderlich"}, {"text": "Keine notarielle Beurkundung", "correct": true, "because": "Einfache Gründung"}, {"text": "Komplexe Buchführung", "correct": false, "because": "EÜR ist einfach"}, {"text": "Einzelentscheidung", "correct": true, "because": "Unternehmer entscheidet allein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen die Einfachheit eines IT-Einzelunternehmens attraktiv?', 3, '[{"text": "Geringer Gründungsaufwand", "correct": true, "because": "Wenige Formalien"}, {"text": "Schnelle Umsetzung von Ideen", "correct": true, "because": "Keine Abstimmung nötig"}, {"text": "Hohe Kapitalanforderung", "correct": false, "because": "Kein Kapital nötig"}, {"text": "Flexibilität bei Entscheidungen", "correct": true, "because": "Unternehmer hat volle Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Einfachheit eines IT-Einzelunternehmens von einer GmbH?', 3, '[{"text": "Keine notarielle Beurkundung beim Einzelunternehmen", "correct": true, "because": "GmbH erfordert Notar"}, {"text": "Keine Mindestkapitalvorgabe beim Einzelunternehmen", "correct": true, "because": "GmbH braucht 25.000 Euro"}, {"text": "GmbH hat geringeren Verwaltungsaufwand", "correct": false, "because": "GmbH hat mehr Aufwand"}, {"text": "Einzelunternehmen hat komplexere Struktur", "correct": false, "because": "Einzelunternehmen ist einfacher"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Einfachheit eines IT-Einzelunternehmens bedeutet geringe Gründungskosten. b) Die Einfachheit erfordert eine notarielle Beurkundung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Einfachheit eines IT-Einzelunternehmens ermöglicht schnelle Entscheidungen. b) Die Einfachheit führt zu komplexer Buchführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheidungen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Einfachheit eines IT-Einzelunternehmens ist ein Vorteil gegenüber der GmbH. b) Die Einfachheit schränkt die Kapitalbeschaffung ein.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Vorteil und Kapitalbeschränkung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Einfachheit eines IT-Einzelunternehmens bedeutet keine Mindestkapitalvorgabe. b) Die Einfachheit erhöht den Verwaltungsaufwand.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Vorgabe ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Einfachheit eines IT-Einzelunternehmens ist ein Vorteil für kleine Projekte. b) Die Einfachheit führt zu beschränkter Haftung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kleine Projekte ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

